// /frontend-react/src/components/Dashboard.js

import React from 'react';

// --- NEW COMPONENT: Minimal Header for Menu Icon on Dashboard ---
const DashboardHeader = ({ onMenuClick, isEasyMode }) => (
    <div style={{ 
        display: 'flex', 
        justifyContent: 'flex-end', // Push content to the right
        padding: '15px 20px', 
        backgroundColor: 'transparent', // Make header transparent to blend with the notification/page background
        position: 'absolute', // Position absolutely over the content/notification
        top: 0,
        right: 0,
        width: '100%',
        zIndex: 15, // Ensure it sits above the notification banner (z-index 10)
    }}>
        <button
            onClick={onMenuClick}
            style={{
                padding: '8px',
                backgroundColor: 'rgba(255, 255, 255, 0.7)', // Semi-transparent button background
                border: '1px solid #ccc',
                borderRadius: '50%',
                cursor: 'pointer',
                fontSize: isEasyMode ? '30px' : '20px',
                color: '#333',
                transition: 'background-color 0.2s',
            }}
            onMouseOver={e => e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 1)'}
            onMouseOut={e => e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.7)'}
        >
            <span role="img" aria-label="Menu">☰</span>
        </button>
    </div>
);
// --- END DashboardHeader ---


const Icon = ({ name, emoji, isActive, onClick, isEasyMode }) => (
    <div 
        onClick={isActive ? onClick : () => isEasyMode && console.log(`Audio: '${name} - Not Available Yet'`)}
        style={{
            padding: '25px', 
            margin: '15px',
            border: `5px solid ${isActive ? '#1A73E8' : '#e0e0e0'}`, 
            borderRadius: '15px', 
            width: '40%',
            textAlign: 'center',
            backgroundColor: isActive ? '#E8F0FE' : '#ffffff', 
            filter: isActive ? 'none' : 'grayscale(80%)', 
            opacity: isActive ? 1 : 0.7, 
            cursor: isActive ? 'pointer' : 'default',
            boxShadow: isActive ? '0 8px 15px rgba(0, 0, 0, 0.3)' : '0 2px 5px rgba(0, 0, 0, 0.1)', 
            transition: 'all 0.3s',
            fontSize: isEasyMode ? '36px' : '20px',
        }}
    >
        <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '85px' : '40px', display: 'block', marginBottom: '10px'}}>{emoji}</span>
        <p style={{fontWeight: 'bold', color: '#333', margin: 0}}>{name}</p>
    </div>
);

function Dashboard({ isEasyMode, goToMedical, onMenuClick }) { // ACCEPT onMenuClick PROP
    return (
        <div style={{ position: 'relative' }}>
            {/* RENDER THE MENU ICON AT THE TOP RIGHT */}
            <DashboardHeader onMenuClick={onMenuClick} isEasyMode={isEasyMode} />

            <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', paddingTop: '40px', paddingBottom: '40px' }}>
                <Icon name="Medical Access" emoji="🏥" isActive={true} onClick={goToMedical} isEasyMode={isEasyMode}/>
                <Icon name="Shopping" emoji="🛒" isActive={false} isEasyMode={isEasyMode}/>
                <Icon name="Community" emoji="🧑‍🤝‍🧑" isActive={false} isEasyMode={isEasyMode}/>
                <Icon name="Home Tasks" emoji="🏡" isActive={false} isEasyMode={isEasyMode}/>
            </div>
        </div>
    );
}

export default Dashboard;
